"use strict";const common_vendor=require("../common/vendor.js");const WEBDAV_CONFIG_KEY="webdav_config";const DATA_FILE_NAME="class-record-data.json";function getWebDAVConfig(){try{const config=common_vendor.index.getStorageSync(WEBDAV_CONFIG_KEY);if(config&&config.url&&config.username&&config.password){return config}return null}catch(e){console.error("获取 WebDAV 配置失败",e);return null}}function saveWebDAVConfig(config){try{common_vendor.index.setStorageSync(WEBDAV_CONFIG_KEY,config);return true}catch(e){console.error("保存 WebDAV 配置失败",e);return false}}function clearWebDAVConfig(){try{common_vendor.index.removeStorageSync(WEBDAV_CONFIG_KEY);return true}catch(e){console.error("清除 WebDAV 配置失败",e);return false}}function isWebDAVConfigured(){return getWebDAVConfig()!==null}function generateBasicAuth(username,password){const credentials=`${username}:${password}`;return"Basic "+base64Encode(credentials)}function base64Encode(str){try{const utf8Bytes=[];for(let i2=0;i2<str.length;i2++){let charCode=str.charCodeAt(i2);if(charCode<128){utf8Bytes.push(charCode)}else if(charCode<2048){utf8Bytes.push(192|charCode>>6);utf8Bytes.push(128|charCode&63)}else if(charCode<55296||charCode>=57344){utf8Bytes.push(224|charCode>>12);utf8Bytes.push(128|charCode>>6&63);utf8Bytes.push(128|charCode&63)}else{i2++;charCode=65536+((charCode&1023)<<10|str.charCodeAt(i2)&1023);utf8Bytes.push(240|charCode>>18);utf8Bytes.push(128|charCode>>12&63);utf8Bytes.push(128|charCode>>6&63);utf8Bytes.push(128|charCode&63)}}const buffer=new ArrayBuffer(utf8Bytes.length);const dataView=new DataView(buffer);for(let i2=0;i2<utf8Bytes.length;i2++){dataView.setUint8(i2,utf8Bytes[i2])}if(typeof wx!=="undefined"&&wx.arrayBufferToBase64){return wx.arrayBufferToBase64(buffer)}if(typeof common_vendor.index!=="undefined"&&common_vendor.index.arrayBufferToBase64){return common_vendor.index.arrayBufferToBase64(buffer)}}catch(e){console.warn("ArrayBuffer 方式编码失败",e)}const base64Chars="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";let result="";let i=0;while(i<str.length){const a=str.charCodeAt(i++);const b=i<str.length?str.charCodeAt(i++):0;const c=i<str.length?str.charCodeAt(i++):0;const bitmap=a<<16|b<<8|c;result+=base64Chars[bitmap>>18&63];result+=base64Chars[bitmap>>12&63];result+=i-2<str.length?base64Chars[bitmap>>6&63]:"=";result+=i-1<str.length?base64Chars[bitmap&63]:"="}return result}async function uploadToWebDAV(data){const config=getWebDAVConfig();if(!config){console.warn("WebDAV 未配置");return false}const{url:url,username:username,password:password}=config;const baseUrl=url.endsWith("/")?url:url+"/";const fileUrl=baseUrl+DATA_FILE_NAME;try{const jsonData=JSON.stringify(data);const authHeader=generateBasicAuth(username,password);return new Promise((resolve=>{common_vendor.index.request({url:fileUrl,method:"PUT",data:jsonData,header:{Authorization:authHeader,"Content-Type":"application/json"},success:res=>{if(res.statusCode>=200&&res.statusCode<300){console.log("WebDAV 上传成功");resolve(true)}else{console.error("WebDAV 上传失败，状态码:",res.statusCode);resolve(false)}},fail:err=>{console.error("WebDAV 上传请求失败",err);resolve(false)}})}))}catch(e){console.error("WebDAV 上传异常",e);return false}}async function downloadFromWebDAV(){const config=getWebDAVConfig();if(!config){console.warn("WebDAV 未配置");return null}const{url:url,username:username,password:password}=config;const baseUrl=url.endsWith("/")?url:url+"/";const fileUrl=baseUrl+DATA_FILE_NAME;try{const authHeader=generateBasicAuth(username,password);return new Promise((resolve=>{common_vendor.index.request({url:fileUrl,method:"GET",header:{Authorization:authHeader,"Content-Type":"application/json"},success:res=>{if(res.statusCode===200&&res.data){console.log("WebDAV 下载成功");const data=res.data;const downloadData={students:data.students,classData:data.classData||data.class};resolve(downloadData)}else if(res.statusCode===404){console.warn("WebDAV 文件不存在");resolve(null)}else{console.error("WebDAV 下载失败，状态码:",res.statusCode);resolve(null)}},fail:err=>{console.error("WebDAV 下载请求失败",err);resolve(null)}})}))}catch(e){console.error("WebDAV 下载异常",e);return null}}async function testWebDAVConnection(config){const{url:url,username:username,password:password}=config;const baseUrl=url.endsWith("/")?url:url+"/";const testFileUrl=baseUrl+"test-connection.json";try{const authHeader=generateBasicAuth(username,password);const testContent=JSON.stringify({test:true,time:(new Date).toISOString()});return new Promise((resolve=>{common_vendor.index.request({url:testFileUrl,method:"PUT",data:testContent,header:{Authorization:authHeader,"Content-Type":"application/json"},success:res=>{if(res.statusCode>=200&&res.statusCode<300){console.log("WebDAV 连接测试成功");resolve(true)}else if(res.statusCode===401){console.error("认证失败，请检查用户名和密码");resolve(false)}else if(res.statusCode===403){console.error("权限不足，无法写入该目录");resolve(false)}else{console.error("WebDAV 连接测试失败，状态码:",res.statusCode);resolve(false)}},fail:err=>{console.error("WebDAV 连接测试请求失败",err);resolve(false)}})}))}catch(e){console.error("WebDAV 连接测试异常",e);return false}}exports.clearWebDAVConfig=clearWebDAVConfig;exports.downloadFromWebDAV=downloadFromWebDAV;exports.getWebDAVConfig=getWebDAVConfig;exports.isWebDAVConfigured=isWebDAVConfigured;exports.saveWebDAVConfig=saveWebDAVConfig;exports.testWebDAVConnection=testWebDAVConnection;exports.uploadToWebDAV=uploadToWebDAV;
